cat > main.gd <<'EOF'
extends Node
var frame := 0
var seq: Array = []
var hdr_c: SubViewportContainer
var sdr_c: SubViewportContainer
var late: Node
func _ready():
	print("driver=", RenderingServer.get_current_rendering_driver_name(), " method=", RenderingServer.get_current_rendering_method(), " thread_model=", ProjectSettings.get_setting("rendering/driver/threads/thread_model", "unset"))
	print("DS=", DisplayServer.get_name(), " win=", get_window().size)
	RenderingServer.frame_pre_draw.connect(_pre)
	for hdr in [true, false]:
		var c := SubViewportContainer.new()
		c.stretch = false
		c.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
		var v := SubViewport.new()
		v.size = Vector2i(8, 4)
		v.use_hdr_2d = hdr
		v.canvas_item_default_texture_filter = Viewport.DEFAULT_CANVAS_ITEM_TEXTURE_FILTER_NEAREST
		c.add_child(v)
		var r := ColorRect.new(); r.color = Color8(128, 64, 200); r.size = Vector2(4, 4); v.add_child(r)
		var r2 := ColorRect.new(); r2.color = Color8(255,255,255); r2.position = Vector2(4,0); r2.size = Vector2(1,4); v.add_child(r2)
		c.scale = Vector2(3, 3)
		c.position = Vector2(10 if hdr else 200, 10)
		add_child(c)
		if hdr: hdr_c = c
		else: sdr_c = c
	var a := CanvasLayer.new(); a.layer = 3; add_child(a)
	var b := CanvasLayer.new(); b.layer = 3; add_child(b)
	var ra := ColorRect.new(); ra.color = Color8(255,0,0); ra.position = Vector2(400,300); ra.size = Vector2(50,50); a.add_child(ra)
	var rb := ColorRect.new(); rb.color = Color8(0,255,0); rb.position = Vector2(400,300); rb.size = Vector2(50,50); b.add_child(rb)
	late = Node.new(); late.process_priority = 1000
	late.set_script(load("res://late.gd")); late.owner_ref = self
	add_child(late)
func _process(_d):
	if frame < 4: seq.append("process%d" % frame)
func _pre():
	if frame < 4:
		seq.append("pre(main=%s)" % (OS.get_thread_caller_id() == OS.get_main_thread_id()))
func _px(img: Image, x: int, y: int) -> String:
	var c := img.get_pixel(x, y)
	return "(%d,%d,%d)" % [roundi(c.r*255), roundi(c.g*255), roundi(c.b*255)]
func _frame_end():
	frame += 1
	if frame == 6:
		print("SEQ ", seq)
		var img := get_viewport().get_texture().get_image()
		print("img size ", img.get_size(), " fmt ", img.get_format())
		for nm in [["hdr", 10], ["sdr", 200]]:
			var x0: int = nm[1]
			print(nm[0], " inside block (8 px in) ", _px(img, x0+6, 10+3), " white col px ", _px(img, x0+13, 13), " edge left-of ", _px(img, x0-1, 13), " first px ", _px(img, x0, 13), " last px ", _px(img, x0+23, 13), " after ", _px(img, x0+24, 13))
		print("layer tie pixel (red a first, green b second; expect green on top) ", _px(img, 420, 320))
		get_tree().quit()
EOF
cat > late.gd <<'EOF'
